package com.gathin.tvhome;

import android.content.Context;
import android.os.StatFs;
import android.text.format.Formatter;
import android.util.Log;
import org.json.JSONArray;
import org.json.JSONObject;
import java.io.*;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.*;

/** Local-only screensaver photo collection: Bing, Unsplash, NASA APOD, NASA Images, Wikimedia POTD, Pexels, Pixabay and public-domain paintings. */
final class PhotoStore {
    static final int JOB_ID=78231, LEGACY_PICSUM_JOB_ID=78232, EXTRA_JOB_ID=78235, BING_JOB_ID=78233, UNSPLASH_JOB_ID=78234;
    static final int LEGACY_PICSUM_NOW_JOB_ID=78332, EXTRA_NOW_JOB_ID=78335, BING_NOW_JOB_ID=78333, UNSPLASH_NOW_JOB_ID=78334;
    static final String MANIFEST="photo_manifest.json";
    static final String SOURCE_BING="bing", SOURCE_UNSPLASH="unsplash", SOURCE_BOTH="all";
    /** Only used to find and delete photos cached by the removed Picsum source. */
    private static final String LEGACY_PICSUM="picsum";
    private static final Object MANIFEST_LOCK=new Object();
    private static final long MB=1024L*1024L, MIN_FREE=2L*1024L*MB, DEFAULT_CAP=200L*MB, FILE_CAP=1536*1024L, EXTRA_FILE_CAP=6L*MB;
    static final class Photo {
        final String file,id,author,source,title,copyright,startdate,downloadLocation,description,altDescription,tags;
        final boolean tracked;
        Photo(String f,String i,String a,String s,String t,String c,String d){this(f,i,a,s,t,c,d,"",false,"","","");}
        Photo(String f,String i,String a,String s,String t,String c,String d,String location,boolean tracked){this(f,i,a,s,t,c,d,location,tracked,"","","");}
        Photo(String f,String i,String a,String s,String t,String c,String d,String location,boolean tracked,String desc,String alt,String tagText){file=f;id=i;author=a;source=s;title=t;copyright=c;startdate=d;downloadLocation=location;this.tracked=tracked;description=desc;altDescription=alt;tags=tagText;}
    }
    private PhotoStore(){}
    static void recordError(Context c,Exception e){String error=e.getClass().getSimpleName()+": "+String.valueOf(e.getMessage());c.getSharedPreferences(Config.SETTINGS_NAME,Context.MODE_PRIVATE).edit().putString("photo_last_error",error).putLong("photo_last_error_at",System.currentTimeMillis()).apply();}
    static void scheduleIfMissingThrottled(Context c){if(!PhotosMaster.on(c))return;if(!c.getSharedPreferences(Config.SETTINGS_NAME,Context.MODE_PRIVATE).getBoolean("dream_photos",true)||!list(c,chosenSource(c)).isEmpty())return;android.content.SharedPreferences p=c.getSharedPreferences(Config.SETTINGS_NAME,Context.MODE_PRIVATE);long now=System.currentTimeMillis();if(now-p.getLong("photo_empty_refresh_at",0)<60L*60*1000)return;p.edit().putLong("photo_empty_refresh_at",now).apply();schedule(c,true);}
    static File dir(Context c){File f=new File(c.getFilesDir(),"photos");if(!f.exists())f.mkdirs();return f;}
    static long cap(Context c){int mb=c.getSharedPreferences(Config.SETTINGS_NAME,Context.MODE_PRIVATE).getInt("photo_storage_mb",200);return (mb==100||mb==200||mb==500?mb*MB:DEFAULT_CAP);}
    static String chosenSource(Context c){android.content.SharedPreferences p=c.getSharedPreferences(Config.SETTINGS_NAME,Context.MODE_PRIVATE);String stored=p.getString("photo_sources",null);if(stored==null){String legacy=p.getString("photo_source","bing,unsplash");Set<String> migrated=PhotoSources.parse(legacy);stored=PhotoSources.serialize(migrated);p.edit().putString("photo_sources",stored).apply();}Set<String> sources=PhotoSources.parse(stored);return PhotoSources.serialize(sources);}
    static void migratePhotoContent(Context c){migrate2115(c);android.content.SharedPreferences prefs=c.getSharedPreferences(Config.SETTINGS_NAME,Context.MODE_PRIVATE);if(prefs.getBoolean("migrated_2_10_1",false))return;synchronized(MANIFEST_LOCK){if(prefs.getBoolean("migrated_2_10_1",false))return;try{Set<String> selected=PhotoSources.parse(chosenSource(c));selected.remove(LEGACY_PICSUM);if(selected.isEmpty()){selected.add(SOURCE_BING);selected.add(SOURCE_UNSPLASH);}prefs.edit().putString("photo_sources",PhotoSources.serialize(selected)).apply();ArrayList<Photo> keep=new ArrayList<>();for(Photo photo:list(c)){if(LEGACY_PICSUM.equals(photo.source))continue;if(SOURCE_UNSPLASH.equals(photo.source)&&PhotoContentFilter.isPeopleLike(photo.description,photo.altDescription,photo.tags))continue;if(SOURCE_UNSPLASH.equals(photo.source)&&(photo.description.isEmpty()&&photo.altDescription.isEmpty()&&photo.tags.isEmpty()))continue;keep.add(photo);}write(c,keep);prefs.edit().putBoolean("migrated_2_10_1",true).apply();}catch(Exception e){recordError(c,e);Log.e("TvHomePhotos","2.10.1 photo migration failed "+e.getClass().getSimpleName()+": "+String.valueOf(e.getMessage()));return;}}schedule(c,true);}
    static Set<String> selectedSources(Context c){return PhotoSources.parse(chosenSource(c));}
    static List<Photo> list(Context c){ArrayList<Photo> out=new ArrayList<>();try{JSONArray a=new JSONObject(readText(new File(c.getFilesDir(),MANIFEST))).optJSONArray("photos");if(a!=null)for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);String name=o.optString("file"),src=o.optString("source",LEGACY_PICSUM);File f=new File(dir(c),name);if(name.matches("[A-Za-z0-9_-]+\\.jpg")&&f.isFile()&&f.length()>0)out.add(new Photo(name,o.optString("id"),o.optString("author"),src,o.optString("title"),o.optString("copyright"),o.optString("startdate"),o.optString("download_location"),o.optBoolean("tracked",false),o.optString("desc"),o.optString("alt"),o.optString("tags")));}}catch(Exception e){if(new File(c.getFilesDir(),MANIFEST).exists()){recordError(c,e);Log.e("TvHomePhotos","manifest read failed "+e.getClass().getSimpleName()+": "+String.valueOf(e.getMessage()));}}return out;}
    static List<Photo> list(Context c,String selected){return list(c,PhotoSources.parse(selected));}
    static List<Photo> list(Context c,Set<String> selected){ArrayList<Photo> bing=new ArrayList<>();LinkedHashMap<String,ArrayList<Photo>> others=new LinkedHashMap<>();for(String s:PhotoSources.KNOWN)if(!SOURCE_BING.equals(s))others.put(s,new ArrayList<>());for(Photo p:list(c))if(selected.contains(p.source)){if(SOURCE_BING.equals(p.source))bing.add(p);else if(others.containsKey(p.source))others.get(p.source).add(p);}bing.sort((a,b)->b.startdate.compareTo(a.startdate));Comparator<Photo> newest=(a,b)->Long.compare(new File(dir(c),b.file).lastModified(),new File(dir(c),a.file).lastModified());int max=0;for(ArrayList<Photo> l:others.values()){l.sort(newest);max=Math.max(max,l.size());}ArrayList<Photo> out=new ArrayList<>(bing);for(int i=0;i<max;i++)for(ArrayList<Photo> l:others.values())if(i<l.size())out.add(l.get(i));return out;}
    static long size(Context c,String selected){long n=0;for(Photo p:list(c,selected))n+=new File(dir(c),p.file).length();return n;}
    static String summary(Context c){List<Photo> photos=list(c);long n=0;LinkedHashMap<String,Integer> counts=new LinkedHashMap<>();for(Photo p:photos){n+=new File(dir(c),p.file).length();counts.put(p.source,(counts.containsKey(p.source)?counts.get(p.source):0)+1);}StringBuilder parts=new StringBuilder();for(String s:PhotoSources.KNOWN)if(counts.containsKey(s)){if(parts.length()>0)parts.append(", ");parts.append(ExtraPhotoSources.label(s)).append(' ').append(counts.get(s));}return c.getString(R.string.photo_count_size,photos.size(),Formatter.formatFileSize(c,n),Formatter.formatFileSize(c,cap(c)))+(parts.length()>0?" ("+parts+")":"");}
    static boolean hasPhotos(Context c){return !list(c,chosenSource(c)).isEmpty();}
    static void schedule(Context c,boolean now){android.app.job.JobScheduler js=(android.app.job.JobScheduler)c.getSystemService(Context.JOB_SCHEDULER_SERVICE);if(js==null)return;if(!PhotosMaster.on(c)){js.cancel(BING_JOB_ID);js.cancel(BING_NOW_JOB_ID);js.cancel(UNSPLASH_JOB_ID);js.cancel(UNSPLASH_NOW_JOB_ID);js.cancel(EXTRA_JOB_ID);js.cancel(EXTRA_NOW_JOB_ID);return;}android.content.ComponentName cn=new android.content.ComponentName(c,PhotoDownloadJob.class);Set<String> sources=selectedSources(c);js.cancel(LEGACY_PICSUM_JOB_ID);js.cancel(LEGACY_PICSUM_NOW_JOB_ID);long day=24L*60*60*1000;if(sources.contains(SOURCE_BING))schedulePeriodic(js,cn,BING_JOB_ID,day);else js.cancel(BING_JOB_ID);boolean unsplash=sources.contains(SOURCE_UNSPLASH)&&ExtraPhotoSources.available(SOURCE_UNSPLASH);if(unsplash)schedulePeriodic(js,cn,UNSPLASH_JOB_ID,day);else js.cancel(UNSPLASH_JOB_ID);boolean extras=false;for(String x:PhotoSources.EXTRAS)if(sources.contains(x)&&ExtraPhotoSources.available(x))extras=true;if(extras)schedulePeriodic(js,cn,EXTRA_JOB_ID,day);else js.cancel(EXTRA_JOB_ID);if(sources.contains(SOURCE_BING)){if(now)scheduleNow(js,cn,BING_NOW_JOB_ID);}else js.cancel(BING_NOW_JOB_ID);if(unsplash){if(now){android.content.SharedPreferences prefs=c.getSharedPreferences(Config.SETTINGS_NAME,Context.MODE_PRIVATE);long time=System.currentTimeMillis();if(time-prefs.getLong("unsplash_now_scheduled_at",0)>=60L*60*1000){prefs.edit().putLong("unsplash_now_scheduled_at",time).apply();scheduleNow(js,cn,UNSPLASH_NOW_JOB_ID);}}}else js.cancel(UNSPLASH_NOW_JOB_ID);if(extras){if(now)scheduleNow(js,cn,EXTRA_NOW_JOB_ID);}else js.cancel(EXTRA_NOW_JOB_ID);}
    private static void schedulePeriodic(android.app.job.JobScheduler js,android.content.ComponentName cn,int id,long period){android.app.job.JobInfo pending=js.getPendingJob(id);if(pending==null||pending.getIntervalMillis()!=period)js.schedule(new android.app.job.JobInfo.Builder(id,cn).setRequiredNetworkType(android.app.job.JobInfo.NETWORK_TYPE_UNMETERED).setPeriodic(period).setPersisted(false).build());}
    private static void scheduleNow(android.app.job.JobScheduler js,android.content.ComponentName cn,int id){js.schedule(new android.app.job.JobInfo.Builder(id,cn).setRequiredNetworkType(android.app.job.JobInfo.NETWORK_TYPE_UNMETERED).setMinimumLatency(0).setOverrideDeadline(1000).setPersisted(false).build());}
    static void refresh(Context c,int jobId)throws Exception{if(!PhotosMaster.on(c))return;synchronized(MANIFEST_LOCK){if(jobId==BING_JOB_ID||jobId==BING_NOW_JOB_ID)refreshBing(c);else if(jobId==UNSPLASH_JOB_ID||jobId==UNSPLASH_NOW_JOB_ID)refreshUnsplash(c);else if(jobId==EXTRA_JOB_ID||jobId==EXTRA_NOW_JOB_ID)refreshExtras(c);logTotals(c);}}
    private static void logTotals(Context c){LinkedHashMap<String,Integer> m=new LinkedHashMap<>();long bytes=0;List<Photo> all=list(c);for(Photo p:all){m.put(p.source,(m.containsKey(p.source)?m.get(p.source):0)+1);bytes+=new File(dir(c),p.file).length();}Log.i("TvHomePhotos","store totals "+m+" total="+all.size()+" size="+(bytes/(1024*1024))+"MB cap="+(cap(c)/(1024*1024))+"MB");}
    static void enforceCap(Context c){synchronized(MANIFEST_LOCK){try{write(c,list(c));}catch(Exception e){Log.e("TvHomePhotos","cap enforcement failed "+e.getClass().getSimpleName()+": "+String.valueOf(e.getMessage()));}}}
    private static void refreshBing(Context c)throws Exception{
        ensureSpace(c);File dir=dir(c);List<Photo> old=list(c);write(c,old);old=list(c);ArrayList<Photo> incoming=new ArrayList<>();HashSet<String> seen=new HashSet<>();
        JSONArray images=new JSONArray();for(String mkt:new String[]{"en-IN","en-US"}){try{JSONArray part=new JSONObject(readUrl("https://www.bing.com/HPImageArchive.aspx?format=js&idx=0&n=8&mkt="+mkt,512*1024)).optJSONArray("images");if(part!=null)for(int k=0;k<part.length();k++)images.put(part.get(k));}catch(Exception e){Log.w("TvHomePhotos","Bing "+mkt+" list failed: "+e.getClass().getSimpleName());}}if(images.length()==0)throw new IOException("No Bing images");
        for(int i=0;i<images.length()&&incoming.size()<16;i++){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("photo job stopped");if(!hasSpace(c))break;JSONObject item=images.getJSONObject(i);String base=item.optString("urlbase"),date=item.optString("startdate");if(base.isEmpty()||!base.matches("/[A-Za-z0-9_./?=&%-]+")||base.contains("..")||!date.matches("[0-9]{8}"))continue;if(!seen.add(ExtraPhotoSources.bingKey(base)))continue;boolean exists=false;for(Photo p:old)if(SOURCE_BING.equals(p.source)&&ExtraPhotoSources.bingKey(p.id).equals(ExtraPhotoSources.bingKey(base))){exists=true;break;}if(exists)continue;String key=base.replaceAll("[^A-Za-z0-9_-]","_");String name="bing_"+key+".jpg";File dst=new File(dir,name),tmp=new File(dir,name+".tmp");try{long n=download(c,"https://www.bing.com"+base+"_1920x1080.jpg",tmp,FILE_CAP);if(n<=0){tmp.delete();continue;}if(dst.exists())dst.delete();if(!tmp.renameTo(dst)){tmp.delete();continue;}incoming.add(new Photo(name,base,"",SOURCE_BING,item.optString("title"),item.optString("copyright"),date));}catch(Exception e){tmp.delete();recordError(c,e);Log.e("TvHomePhotos","photo download failed "+e.getClass().getSimpleName()+": "+String.valueOf(e.getMessage()));if(Thread.currentThread().isInterrupted())throw e;}}
        if(incoming.isEmpty())return;ArrayList<Photo> all=new ArrayList<>(old);all.addAll(incoming);all.sort((a,b)->{if(!a.source.equals(b.source))return SOURCE_BING.equals(a.source)?-1:1;return b.startdate.compareTo(a.startdate);});write(c,all);
    }
    private static void refreshUnsplash(Context c)throws Exception{
        String key=BuildConfig.UNSPLASH_ACCESS_KEY;
        if(key==null||key.trim().isEmpty()){if(!c.getSharedPreferences(Config.SETTINGS_NAME,Context.MODE_PRIVATE).getBoolean("unsplash_missing_key_logged",false)){Log.i("TvHomePhotos","Unsplash source skipped: no local API key configured");c.getSharedPreferences(Config.SETTINGS_NAME,Context.MODE_PRIVATE).edit().putBoolean("unsplash_missing_key_logged",true).apply();}return;}
        if(!reserveUnsplashCall(c))return;
        ensureSpace(c);File folder=dir(c);List<Photo> old=list(c);write(c,old);old=list(c);HashSet<String> existing=new HashSet<>();for(Photo p:old)if(SOURCE_UNSPLASH.equals(p.source))existing.add(p.id);ArrayList<Photo> incoming=new ArrayList<>();
        String endpoint="https://api.unsplash.com/photos/random?count=30&orientation=landscape&content_filter=high&query=landscape%20nature";
        String json;
        try{json=readApi(endpoint,key,1024*1024);}catch(ApiHttpException e){if(e.code<400||e.code>=500)throw e;if(!reserveUnsplashCall(c))return;json=readApi("https://api.unsplash.com/photos/random?count=30&orientation=landscape&content_filter=high&query=nature",key,1024*1024);}
        for(UnsplashPhotoParser.Entry item:UnsplashPhotoParser.parse(json)){
            if(incoming.size()>=30)break;if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("photo job stopped");if(PhotoContentFilter.isPeopleLike(item.description,item.altDescription,item.tags)||!hasSpace(c)||existing.contains(item.id))continue;
            String name="unsplash_"+item.id.replaceAll("[^A-Za-z0-9_-]","_")+".jpg";File dst=new File(folder,name),tmp=new File(folder,name+".tmp");
            try{long n=0;try{n=download(c,UnsplashPhotoParser.sizedUrl(item.rawUrl),tmp,FILE_CAP);}catch(Exception primary){tmp.delete();n=download(c,item.regularUrl,tmp,FILE_CAP);}if(n<=0){tmp.delete();continue;}if(dst.exists())dst.delete();if(!tmp.renameTo(dst)){tmp.delete();continue;}try{trackUnsplashDownload(item.downloadLocation,key,0);}catch(Exception e){Log.w("TvHomePhotos","Unsplash download tracking request failed: "+e.getClass().getSimpleName());}incoming.add(new Photo(name,item.id,item.author,SOURCE_UNSPLASH,"","","",item.downloadLocation,true,item.description,item.altDescription,item.tags));existing.add(item.id);}
            catch(Exception e){tmp.delete();recordError(c,e);Log.e("TvHomePhotos","photo download failed "+e.getClass().getSimpleName()+": "+String.valueOf(e.getMessage()));if(Thread.currentThread().isInterrupted())throw e;}
        }
        if(!incoming.isEmpty()){ArrayList<Photo> all=new ArrayList<>(old);all.addAll(incoming);write(c,all);}
    }
    private static boolean reserveUnsplashCall(Context c){android.content.SharedPreferences p=c.getSharedPreferences(Config.SETTINGS_NAME,Context.MODE_PRIVATE);long now=System.currentTimeMillis();String stored=p.getString("unsplash_list_calls","" );ArrayList<Long> recent=new ArrayList<>();for(String value:stored.split(","))try{long at=Long.parseLong(value);if(now-at<24L*60*60*1000&&at<=now)recent.add(at);}catch(Exception ignored){}if(recent.size()>=4){Log.i("TvHomePhotos","Unsplash list request skipped: daily call limit reached");return false;}recent.add(now);StringBuilder out=new StringBuilder();for(Long at:recent){if(out.length()>0)out.append(',');out.append(at);}p.edit().putString("unsplash_list_calls",out.toString()).apply();return true;}
    private static final class ApiHttpException extends IOException{final int code;ApiHttpException(int code){super("Unsplash HTTP "+code);this.code=code;}}
    private static String readApi(String value,String key,int cap)throws Exception{return readApi(value,key,cap,0);}
    private static String readApi(String value,String key,int cap,int redirects)throws Exception{URL u=new URL(value);if(!isAllowedPhotoUrl(u)||!"api.unsplash.com".equalsIgnoreCase(u.getHost())||redirects>5)throw new IOException("URL outside Unsplash API host");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(10000);c.setReadTimeout(20000);c.setRequestProperty("Authorization","Client-ID "+key);c.setRequestProperty("Accept-Version","v1");int code=c.getResponseCode();String remaining=c.getHeaderField("X-Ratelimit-Remaining");if(remaining!=null)Log.i("TvHomePhotos","Unsplash X-Ratelimit-Remaining="+remaining);if(code>=300&&code<400){String location=c.getHeaderField("Location");c.disconnect();if(location==null)throw new IOException("missing redirect");return readApi(new URL(u,location).toString(),key,cap,redirects+1);}if(code<200||code>=300){c.disconnect();throw new ApiHttpException(code);}try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n,total=0;while((n=in.read(b))!=-1){total+=n;if(total>cap)throw new IOException("response too large");out.write(b,0,n);}return out.toString("UTF-8");}finally{c.disconnect();}}
    private static void trackUnsplashDownload(String value,String key,int redirects)throws Exception{URL u=new URL(value);if(!isAllowedPhotoUrl(u)||!"api.unsplash.com".equalsIgnoreCase(u.getHost())||redirects>5)throw new IOException("URL outside Unsplash API host");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(10000);c.setReadTimeout(20000);c.setRequestProperty("Authorization","Client-ID "+key);c.setRequestProperty("Accept-Version","v1");int code=c.getResponseCode();String remaining=c.getHeaderField("X-Ratelimit-Remaining");if(remaining!=null)Log.i("TvHomePhotos","Unsplash X-Ratelimit-Remaining="+remaining);if(code>=300&&code<400){String location=c.getHeaderField("Location");c.disconnect();if(location==null)throw new IOException("missing redirect");trackUnsplashDownload(new URL(u,location).toString(),key,redirects+1);return;}c.disconnect();if(code<200||code>=300)throw new IOException("Unsplash tracking HTTP "+code);}
    private static ArrayList<Photo> without(List<Photo> items,String source){ArrayList<Photo> out=new ArrayList<>();for(Photo p:items)if(!source.equals(p.source))out.add(p);return out;}
    private static void write(Context c,List<Photo> photos)throws Exception{synchronized(MANIFEST_LOCK){writeLocked(c,photos);}}
    private static void writeLocked(Context c,List<Photo> photos)throws Exception{
        ArrayList<Photo> keep=new ArrayList<>(photos);long total=0;for(Photo p:keep)total+=new File(dir(c),p.file).length();
        while(total>cap(c)){Photo p=removeOldestNonBing(keep,dir(c));if(p==null)p=removeOldestBingBeyondNewestEight(keep);if(p==null)break;total-=new File(dir(c),p.file).length();}
        JSONArray a=new JSONArray();HashSet<String> live=new HashSet<>();for(Photo p:keep){JSONObject o=new JSONObject();o.put("file",p.file);o.put("id",p.id);o.put("author",p.author);o.put("source",p.source);o.put("title",p.title);o.put("copyright",p.copyright);o.put("startdate",p.startdate);o.put("download_location",p.downloadLocation);o.put("tracked",p.tracked);if(SOURCE_UNSPLASH.equals(p.source)){o.put("desc",p.description);o.put("alt",p.altDescription);o.put("tags",p.tags);}a.put(o);live.add(p.file);}JSONObject root=new JSONObject();root.put("photos",a);File manifest=new File(c.getFilesDir(),MANIFEST),temp=new File(c.getFilesDir(),MANIFEST+".tmp");try(FileOutputStream out=new FileOutputStream(temp)){out.write(root.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));out.getFD().sync();}if(manifest.exists())manifest.delete();if(!temp.renameTo(manifest))throw new IOException("Could not replace photo manifest");File[] files=dir(c).listFiles();if(files!=null)for(File f:files)if(f.isFile()&&f.getName().endsWith(".jpg")&&!live.contains(f.getName()))f.delete();
    }
    /** Over the cap: drop the oldest non-Bing photo first (by file time), then Bing beyond the newest 16. */
    private static Photo removeOldestNonBing(List<Photo> all,File folder){Photo oldest=null;long time=Long.MAX_VALUE;for(Photo p:all)if(!SOURCE_BING.equals(p.source)){long t=new File(folder,p.file).lastModified();if(t<time){oldest=p;time=t;}}if(oldest!=null)all.remove(oldest);return oldest;}
    private static Photo removeOldestUnsplash(List<Photo> all,File folder){Photo oldest=null;long time=Long.MAX_VALUE;for(Photo p:all)if(SOURCE_UNSPLASH.equals(p.source)){long candidate=new File(folder,p.file).lastModified();if(candidate<time){oldest=p;time=candidate;}}if(oldest!=null)all.remove(oldest);return oldest;}
    private static Photo removeOldestBingBeyondNewestEight(List<Photo> all){ArrayList<Photo> bing=new ArrayList<>();for(Photo p:all)if(SOURCE_BING.equals(p.source))bing.add(p);bing.sort((a,b)->b.startdate.compareTo(a.startdate));if(bing.size()<=16)return null;Photo p=bing.get(bing.size()-1);all.remove(p);return p;}
    private static boolean hasSpace(Context c){return new StatFs(c.getFilesDir().getAbsolutePath()).getAvailableBytes()>=MIN_FREE;}
    private static void ensureSpace(Context c)throws IOException{if(!hasSpace(c))throw new IOException("Insufficient data partition space for photo download");}
    private static long download(Context c,String url,File out,long cap)throws Exception{if(cap>FILE_CAP)cap=Math.min(cap,EXTRA_FILE_CAP);ensureSpace(c);try(InputStream in=open(url,0);FileOutputStream dst=new FileOutputStream(out)){byte[] b=new byte[16384];long n=0;int r;while((r=in.read(b))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("photo job stopped");ensureSpace(c);n+=r;if(n>cap)throw new IOException("photo over "+(cap/1024)+" KB");dst.write(b,0,r);ensureSpace(c);}return n;}}
    private static String readUrl(String url,int cap)throws Exception{return readUrl(url,cap,null);}
    private static String readUrl(String url,int cap,String auth)throws Exception{try(InputStream in=open(url,0,auth);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int r,n=0;while((r=in.read(b))!=-1){n+=r;if(n>cap)throw new IOException("response too large");out.write(b,0,r);}return out.toString("UTF-8");}}
    static boolean isAllowedPhotoUrl(URL u){return PhotoUrlPolicy.isAllowed(u);}
    private static InputStream open(String value,int redirects)throws Exception{return open(value,redirects,null);}
    private static InputStream open(String value,int redirects,String auth)throws Exception{URL u=new URL(value);if(!PhotoUrlPolicy.isAllowed(u)||redirects>5)throw new IOException("URL outside photo hosts");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(10000);c.setReadTimeout(20000);c.setRequestProperty("User-Agent","RaiderLauncher/2.11 (Android TV screensaver)");if(auth!=null)c.setRequestProperty("Authorization",auth);int code=c.getResponseCode();if(code>=300&&code<400){String location=c.getHeaderField("Location");c.disconnect();if(location==null)throw new IOException("missing redirect");URL next=new URL(u,location);return open(next.toString(),redirects+1,next.getHost().equalsIgnoreCase(u.getHost())?auth:null);}if(code<200||code>=300){c.disconnect();throw new IOException("Photo HTTP "+code);}return new DisconnectingInputStream(c);}
    private static String readText(File f)throws Exception{return new String(java.nio.file.Files.readAllBytes(f.toPath()),java.nio.charset.StandardCharsets.UTF_8);}
    private static final class DisconnectingInputStream extends FilterInputStream{final HttpURLConnection c;DisconnectingInputStream(HttpURLConnection c)throws Exception{super(c.getInputStream());this.c=c;}public void close()throws IOException{try{super.close();}finally{c.disconnect();}}}

    /** 2.11.5: drop Picsum (setting and cached photos) and switch the new free sources on once. */
    private static void migrate2115(Context c){android.content.SharedPreferences p=c.getSharedPreferences(Config.SETTINGS_NAME,Context.MODE_PRIVATE);if(p.getBoolean("migrated_2_11_5",false))return;synchronized(MANIFEST_LOCK){if(p.getBoolean("migrated_2_11_5",false))return;try{String stored=p.getString("photo_sources",p.getString("photo_source",""));Set<String> sel=PhotoSources.parse(stored);for(String x:PhotoSources.EXTRAS)sel.add(x);p.edit().putString("photo_sources",PhotoSources.serialize(sel)).remove("photo_source").apply();ArrayList<Photo> keep=new ArrayList<>();int dropped=0;for(Photo ph:list(c)){if(LEGACY_PICSUM.equals(ph.source)){dropped++;continue;}keep.add(ph);}write(c,keep);File[] files=dir(c).listFiles();if(files!=null)for(File f:files)if(f.getName().startsWith("picsum_"))f.delete();android.app.job.JobScheduler js=(android.app.job.JobScheduler)c.getSystemService(Context.JOB_SCHEDULER_SERVICE);if(js!=null){js.cancel(LEGACY_PICSUM_JOB_ID);js.cancel(LEGACY_PICSUM_NOW_JOB_ID);}p.edit().putBoolean("migrated_2_11_5",true).apply();Log.i("TvHomePhotos","2.11.5 migration: removed "+dropped+" Picsum photos, sources="+PhotoSources.serialize(sel));}catch(Exception e){recordError(c,e);Log.e("TvHomePhotos","2.11.5 migration failed "+e.getClass().getSimpleName()+": "+String.valueOf(e.getMessage()));return;}}schedule(c,true);}
    private static final class Candidate{final String id,url,fallback,title,credit,text;Candidate(String id,String url,String fallback,String title,String credit,String text){this.id=id==null?"":id;this.url=url;this.fallback=fallback;this.title=title==null?"":title.trim();this.credit=credit==null?"":credit.trim();this.text=text==null?"":text;}}
    /** One daily job for the six extra sources; each is independent so one failing source does not stop the others. */
    private static void refreshExtras(Context c)throws Exception{Set<String> sel=selectedSources(c);for(String src:PhotoSources.EXTRAS){if(!sel.contains(src)||!ExtraPhotoSources.available(src))continue;if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("photo job stopped");try{saveCandidates(c,src,fetchCandidates(src),ExtraPhotoSources.limit(src));}catch(InterruptedIOException e){throw e;}catch(Exception e){recordError(c,e);Log.e("TvHomePhotos",src+" refresh failed "+e.getClass().getSimpleName()+": "+String.valueOf(e.getMessage()));}}}
    private static void saveCandidates(Context c,String src,List<Candidate> cands,int limit)throws Exception{ensureSpace(c);File folder=dir(c);HashSet<String> existing=new HashSet<>();for(Photo p:list(c))if(src.equals(p.source))existing.add(p.id);ArrayList<Photo> incoming=new ArrayList<>();int skipped=0,filtered=0,small=0;
        for(Candidate cd:cands){if(incoming.size()>=limit)break;if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("photo job stopped");if(!hasSpace(c))break;if(cd.id.isEmpty()||cd.url==null||cd.url.isEmpty()||existing.contains(cd.id))continue;boolean longText=PhotoSources.APOD.equals(src)||PhotoSources.WIKIMEDIA.equals(src);if(PhotoContentFilter.isPeopleLike(cd.title,longText?"":cd.text)){skipped++;filtered++;continue;}String name=src+"_"+cd.id.replaceAll("[^A-Za-z0-9_-]","_");if(name.length()>80)name=name.substring(0,80);name+=".jpg";File dst=new File(folder,name),tmp=new File(folder,name+".tmp");
            try{if(PhotoSources.WIKIMEDIA.equals(src)&&cands.indexOf(cd)>0)Thread.sleep(2000);long n;try{n=download(c,cd.url,tmp,capFor(src));}catch(InterruptedIOException e){throw e;}catch(Exception first){tmp.delete();if(cd.fallback==null||cd.fallback.isEmpty())throw first;n=download(c,cd.fallback,tmp,capFor(src));}if(n<=0||!landscapeEnough(tmp,PhotoSources.APOD.equals(src)?1024:1280)){tmp.delete();skipped++;small++;continue;}if(dst.exists())dst.delete();if(!tmp.renameTo(dst)){tmp.delete();continue;}incoming.add(new Photo(name,cd.id,cd.credit,src,cd.title,cd.credit,"","",false,"","",""));existing.add(cd.id);}
            catch(InterruptedIOException e){tmp.delete();throw e;}catch(Exception e){tmp.delete();skipped++;Log.w("TvHomePhotos",src+" photo skipped: "+e.getClass().getSimpleName()+": "+String.valueOf(e.getMessage()));}}
        Log.i("TvHomePhotos",src+" candidates="+cands.size()+" added="+incoming.size()+" skipped="+skipped+" (people filter "+filtered+", too small/portrait "+small+")");if(!incoming.isEmpty()){ArrayList<Photo> all=new ArrayList<>(list(c));all.addAll(incoming);write(c,all);}}
    /** Photos only, landscape and at least 1280 px wide (bounds only, nothing decoded into memory). */
    private static long capFor(String src){return PhotoSources.APOD.equals(src)||PhotoSources.NASA.equals(src)||PhotoSources.WIKIMEDIA.equals(src)?EXTRA_FILE_CAP:4L*MB;}
    private static boolean rateLimited(Exception e){return String.valueOf(e.getMessage()).contains("HTTP 429");}
    private static boolean landscapeEnough(File f,int minWidth){android.graphics.BitmapFactory.Options o=new android.graphics.BitmapFactory.Options();o.inJustDecodeBounds=true;android.graphics.BitmapFactory.decodeFile(f.getAbsolutePath(),o);return o.outWidth>=minWidth&&o.outWidth>o.outHeight;}
    private static List<Candidate> fetchCandidates(String src)throws Exception{ArrayList<Candidate> out=new ArrayList<>();Random rnd=new Random();
        if(PhotoSources.APOD.equals(src)){String key=ExtraPhotoSources.nasaKey();ArrayList<JSONObject> items=new ArrayList<>();try{items.add(new JSONObject(readUrl("https://api.nasa.gov/planetary/apod?thumbs=false&api_key="+key,256*1024)));}catch(Exception e){if(rateLimited(e)){Log.w("TvHomePhotos","APOD rate-limited (HTTP 429, "+("DEMO_KEY".equals(key)?"shared DEMO_KEY":"own key")+"); will retry next refresh");return out;}Log.w("TvHomePhotos","APOD today failed: "+e.getClass().getSimpleName()+": "+e.getMessage());}try{JSONArray r=new JSONArray(readUrl("https://api.nasa.gov/planetary/apod?thumbs=false&count=10&api_key="+key,1024*1024));for(int i=0;i<r.length();i++)items.add(r.getJSONObject(i));}catch(Exception e){Log.w("TvHomePhotos","APOD random failed: "+(rateLimited(e)?"HTTP 429 rate limit, will retry next refresh":e.getClass().getSimpleName()+": "+e.getMessage()));}
            for(JSONObject o:items){if(!"image".equals(o.optString("media_type")))continue;String url=o.optString("url"),hd=o.optString("hdurl");if(url.isEmpty()&&hd.isEmpty())continue;String credit=o.optString("copyright","").replace('\n',' ').trim();out.add(new Candidate(o.optString("date"),hd.isEmpty()?url:hd,hd.isEmpty()?null:url,o.optString("title"),credit.isEmpty()?"NASA APOD":credit+" / NASA APOD",o.optString("explanation")));}}
        else if(PhotoSources.NASA.equals(src)){ArrayList<JSONObject> pick=new ArrayList<>();ArrayList<String> terms=new ArrayList<>(Arrays.asList("nebula","galaxy","earth","aurora","saturn","jupiter"));Collections.shuffle(terms,rnd);for(int q=0;q<2;q++){try{JSONArray found=new JSONObject(readUrl("https://images-api.nasa.gov/search?q="+terms.get(q)+"&media_type=image&page_size=60",3*1024*1024)).getJSONObject("collection").optJSONArray("items");if(found!=null)for(int i=0;i<found.length();i++)pick.add(found.getJSONObject(i));}catch(Exception e){Log.w("TvHomePhotos","NASA search "+terms.get(q)+" failed: "+e.getClass().getSimpleName()+": "+e.getMessage());}}Log.i("TvHomePhotos","NASA search results="+pick.size());{Collections.shuffle(pick,rnd);int tries=0;for(JSONObject it:pick){if(out.size()>=ExtraPhotoSources.limit(src)+5||tries++>30)break;JSONArray data=it.optJSONArray("data");if(data==null||data.length()==0)continue;JSONObject d=data.getJSONObject(0);String id=d.optString("nasa_id"),href=it.optString("href");if(id.isEmpty()||href.isEmpty())continue;JSONArray kw=d.optJSONArray("keywords");try{JSONArray assets=new JSONArray(readUrl(href.replace("http://","https://"),256*1024));String orig=null,large=null,medium=null;for(int k=0;k<assets.length();k++){String a=assets.getString(k).replace("http://","https://"),low=a.toLowerCase(Locale.ROOT);if(low.endsWith("~orig.jpg"))orig=a;else if(low.endsWith("~large.jpg"))large=a;else if(low.endsWith("~medium.jpg"))medium=a;}String best=orig!=null?orig:large!=null?large:medium;String fb=orig!=null?(large!=null?large:medium):(large!=null?medium:null);if(best==null)continue;out.add(new Candidate(id,best,fb,d.optString("title"),"NASA Image Library",d.optString("description")+" "+(kw==null?"":kw.toString())));}catch(Exception e){Log.w("TvHomePhotos","NASA asset list failed: "+e.getClass().getSimpleName());}}}}
        else if(PhotoSources.WIKIMEDIA.equals(src)){Calendar cal=Calendar.getInstance(TimeZone.getTimeZone("UTC"));for(int day=0;day<10;day++){String path=String.format(Locale.US,"%04d/%02d/%02d",cal.get(Calendar.YEAR),cal.get(Calendar.MONTH)+1,cal.get(Calendar.DAY_OF_MONTH));cal.add(Calendar.DAY_OF_MONTH,-1);try{JSONObject img=new JSONObject(readUrl("https://api.wikimedia.org/feed/v1/wikipedia/en/featured/"+path,3*1024*1024)).optJSONObject("image");if(img==null)continue;JSONObject full=img.optJSONObject("image");if(full==null)continue;int w=full.optInt("width"),h=full.optInt("height");if(w<1280||w<=h)continue;String source=full.optString("source");String title=img.optString("title").replaceFirst("^File:","").replaceAll("\\.[A-Za-z]{3,4}$","").replace('_',' ');JSONObject artist=img.optJSONObject("artist");String credit=artist==null?"":ExtraPhotoSources.stripHtml(artist.optString("text"));JSONObject desc=img.optJSONObject("description");out.add(new Candidate(path.replace("/",""),w>1920?ExtraPhotoSources.wikimediaThumb(source,1920):source,w>1920?source:null,title,(credit.isEmpty()?"":credit+" / ")+"Wikimedia Commons",desc==null?"":ExtraPhotoSources.stripHtml(desc.optString("text"))));}catch(Exception e){Log.w("TvHomePhotos","Wikimedia "+path+" failed: "+e.getClass().getSimpleName());}}}
        else if(PhotoSources.PEXELS.equals(src)){JSONObject r=new JSONObject(readUrl("https://api.pexels.com/v1/search?query=nature%20landscape&orientation=landscape&per_page=30&page="+(1+rnd.nextInt(10)),1024*1024,BuildConfig.PEXELS_API_KEY.trim()));JSONArray ph=r.optJSONArray("photos");if(ph!=null)for(int i=0;i<ph.length();i++){JSONObject o=ph.getJSONObject(i);if(o.optInt("width")<1280||o.optInt("width")<=o.optInt("height"))continue;JSONObject s=o.optJSONObject("src");if(s==null)continue;out.add(new Candidate(String.valueOf(o.optLong("id")),s.optString("large2x"),s.optString("original"),o.optString("alt"),"Photo by "+o.optString("photographer")+" on Pexels",o.optString("alt")));}}
        else if(PhotoSources.PIXABAY.equals(src)){JSONObject r=new JSONObject(readUrl("https://pixabay.com/api/?key="+java.net.URLEncoder.encode(BuildConfig.PIXABAY_API_KEY.trim(),"UTF-8")+"&q=nature+landscape&image_type=photo&orientation=horizontal&safesearch=true&min_width=1280&per_page=30&page="+(1+rnd.nextInt(5)),1024*1024));JSONArray hits=r.optJSONArray("hits");if(hits!=null)for(int i=0;i<hits.length();i++){JSONObject o=hits.getJSONObject(i);String tags=o.optString("tags");String title=tags.isEmpty()?"Pixabay":Character.toUpperCase(tags.charAt(0))+tags.substring(1).split(",")[0];out.add(new Candidate(String.valueOf(o.optLong("id")),o.optString("largeImageURL"),null,title,"Photo by "+o.optString("user")+" on Pixabay",tags));}}
        else if(PhotoSources.ART.equals(src)){try{JSONObject r=new JSONObject(readUrl("https://api.artic.edu/api/v1/artworks/search?q=landscape&query%5Bterm%5D%5Bis_public_domain%5D=true&fields=id,title,artist_title,image_id,thumbnail,is_public_domain&limit=40&page="+(1+rnd.nextInt(10)),1024*1024));JSONArray d=r.optJSONArray("data");if(d!=null)for(int i=0;i<d.length();i++){JSONObject o=d.getJSONObject(i);String img=o.optString("image_id");if(img.isEmpty()||"null".equals(img)||!o.optBoolean("is_public_domain",true))continue;JSONObject th=o.optJSONObject("thumbnail");if(th!=null&&(th.optInt("width")<1280||th.optInt("width")<=th.optInt("height")))continue;String artist=o.optString("artist_title");if("null".equals(artist))artist="";out.add(new Candidate("aic"+o.optLong("id"),"https://www.artic.edu/iiif/2/"+img+"/full/1686,/0/default.jpg","https://www.artic.edu/iiif/2/"+img+"/full/1280,/0/default.jpg",o.optString("title"),(artist.isEmpty()?"":artist+" / ")+"Art Institute of Chicago",o.optString("title")));}}catch(Exception e){Log.w("TvHomePhotos","AIC failed: "+e.getClass().getSimpleName());}
            try{JSONArray ids=new JSONObject(readUrl("https://collectionapi.metmuseum.org/public/collection/v1/search?hasImages=true&isPublicDomain=true&q=landscape%20painting",3*1024*1024)).optJSONArray("objectIDs");if(ids!=null){ArrayList<Long> all=new ArrayList<>();for(int i=0;i<ids.length();i++)all.add(ids.getLong(i));Collections.shuffle(all,rnd);int n=0;for(long id:all){if(n++>=12)break;try{JSONObject o=new JSONObject(readUrl("https://collectionapi.metmuseum.org/public/collection/v1/objects/"+id,256*1024));if(!o.optBoolean("isPublicDomain"))continue;String img=o.optString("primaryImage");if(img.isEmpty())continue;String artist=o.optString("artistDisplayName");out.add(new Candidate("met"+id,img,o.optString("primaryImageSmall"),o.optString("title"),(artist.isEmpty()?"":artist+" / ")+"The Met",o.optString("title")+" "+o.optString("classification")));}catch(Exception e){Log.w("TvHomePhotos","Met object failed: "+e.getClass().getSimpleName());}}}}catch(Exception e){Log.w("TvHomePhotos","Met search failed: "+e.getClass().getSimpleName());}
            Collections.shuffle(out,rnd);}
        return out;}
}
